From 36a967fe8198058fb0315db96156e2994492e9fe Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sun, 22 Nov 2026 01:19:28 +0100
Subject: [PATCH] HolidayRegionsModel: add language roles

Countries with one holiday file per language, like Belgium or Serbia,
have regions with the same name and description. Add a role with the
name of the file's language and one telling if its country has several.

BUG: 482125
---
 src/declarative/holidayregionsmodel.cpp | 46 +++++++++++++++++++++++++
 src/declarative/holidayregionsmodel.h   |  2 ++
 2 files changed, 48 insertions(+)

diff --git a/src/declarative/holidayregionsmodel.cpp b/src/declarative/holidayregionsmodel.cpp
index 08d9870..a41670e 100644
--- a/src/declarative/holidayregionsmodel.cpp
+++ b/src/declarative/holidayregionsmodel.cpp
@@ -10,10 +10,46 @@

 #include "../holidayregion.h"

+#include <QCoreApplication>
+#include <QLocale>
+
+static QString countryPart(const QString &regionCode)
+{
+    return regionCode.left(regionCode.lastIndexOf(QLatin1Char('_')));
+}
+
+static QString languageName(const QString &languageCode)
+{
+    const qsizetype separator = languageCode.indexOf(QLatin1Char('@'));
+    const QString modifier = separator < 0 ? QString() : languageCode.mid(separator + 1);
+    const QLocale locale(languageCode.left(separator));
+    if (locale.language() == QLocale::C) {
+        return languageCode;
+    }
+
+    const QString language = QLocale::languageToString(locale.language());
+    QString variant;
+    if (modifier == QLatin1String("latin")) {
+        variant = QLocale::scriptToString(QLocale::LatinScript);
+    } else if (modifier == QLatin1String("cyrillic")) {
+        variant = QLocale::scriptToString(QLocale::CyrillicScript);
+    } else if (modifier == QLatin1String("ijekavian")) {
+        variant = QCoreApplication::translate("HolidayRegion", "Ijekavian", "Serbian language variant");
+    } else if (modifier == QLatin1String("ijekavianlatin")) {
+        variant = QCoreApplication::translate("HolidayRegion", "Ijekavian Latin", "Serbian language variant");
+    }
+
+    if (variant.isEmpty()) {
+        return language;
+    }
+    return QCoreApplication::translate("HolidayRegion", "%1 (%2)", "Holiday file language, %1 = language, %2 = script or variant").arg(language, variant);
+}
+
 class HolidayRegionsDeclarativeModel::Private
 {
 public:
     QStringList regionCodes;
+    QHash<QString, int> filesPerCountry;
 };

 HolidayRegionsDeclarativeModel::HolidayRegionsDeclarativeModel(QObject *parent)
@@ -25,6 +61,10 @@ HolidayRegionsDeclarativeModel::HolidayRegionsDeclarativeModel(QObject *parent)
     // This can happen if two copies of the data exist
     // in the system and both are read by KHolidays.
     d->regionCodes.removeDuplicates();
+
+    for (const QString &regionCode : std::as_const(d->regionCodes)) {
+        d->filesPerCountry[countryPart(regionCode)]++;
+    }
 }

 HolidayRegionsDeclarativeModel::~HolidayRegionsDeclarativeModel()
@@ -64,6 +104,10 @@ QVariant HolidayRegionsDeclarativeModel::data(const QModelIndex &index, int role
             return KHolidays::HolidayRegion::name(regionCode);
         case HolidayRegionsDeclarativeModel::DescriptionRole:
             return KHolidays::HolidayRegion::description(regionCode);
+        case HolidayRegionsDeclarativeModel::LanguageRole:
+            return languageName(KHolidays::HolidayRegion::languageCode(regionCode));
+        case HolidayRegionsDeclarativeModel::HasLanguageVariantsRole:
+            return d->filesPerCountry.value(countryPart(regionCode)) > 1;
         }
         break;
     case NameColumn:
@@ -102,6 +146,8 @@ QHash<int, QByteArray> HolidayRegionsDeclarativeModel::roleNames() const
     roles.insert(HolidayRegionsDeclarativeModel::RegionRole, QByteArrayLiteral("region"));
     roles.insert(HolidayRegionsDeclarativeModel::NameRole, QByteArrayLiteral("name"));
     roles.insert(HolidayRegionsDeclarativeModel::DescriptionRole, QByteArrayLiteral("description"));
+    roles.insert(HolidayRegionsDeclarativeModel::LanguageRole, QByteArrayLiteral("language"));
+    roles.insert(HolidayRegionsDeclarativeModel::HasLanguageVariantsRole, QByteArrayLiteral("hasLanguageVariants"));

     return roles;
 }
diff --git a/src/declarative/holidayregionsmodel.h b/src/declarative/holidayregionsmodel.h
index c3b050c..d670524 100644
--- a/src/declarative/holidayregionsmodel.h
+++ b/src/declarative/holidayregionsmodel.h
@@ -24,6 +24,8 @@ public:
         RegionRole = Qt::UserRole + 1,
         NameRole,
         DescriptionRole,
+        LanguageRole,
+        HasLanguageVariantsRole,
     };
     enum Columns {
         RegionColumn,
